package org.marketreview.nativeapp;
import org.json.*;
import java.time.LocalDate;
import java.util.*;
/** Existing ledger semantics, explicit cash and immutable historical snapshots. */
final class AccountAnalysis {
 static Object known(Object v,boolean nonnegative){if(!(v instanceof Number))return JSONObject.NULL;double n=((Number)v).doubleValue();return Double.isFinite(n)&&Math.abs(n)<=1e15&&(!nonnegative||n>=0)?n:JSONObject.NULL;}
 static double round(double n){return Math.round(n*100)/100.;}
 static Object add(Object a,Object b){return a instanceof Number&&b instanceof Number?round(((Number)a).doubleValue()+((Number)b).doubleValue()):JSONObject.NULL;}
 static JSONObject evaluate(JSONObject account,JSONArray trades,JSONObject quotes,JSONArray reports)throws Exception{
  String id=account.optString("id");BusinessStore.require(!id.isEmpty(),"请选择明确账户");JSONObject p=BusinessStore.portfolio(trades,quotes,id);Object cash=known(account.opt("cashBalance"),true),assets=add(p.opt("marketValue"),cash),totalPnl=add(p.opt("realized"),p.opt("unrealized"));JSONArray positions=new JSONArray(),source=p.getJSONArray("positions");for(int i=0;i<source.length();i++){JSONObject row=new JSONObject(source.getJSONObject(i).toString());row.put("costWeightPercent",p.optDouble("cost")>0?round(row.optDouble("cost")/p.getDouble("cost")*100):JSONObject.NULL).put("marketWeightPercent",assets instanceof Number&&((Number)assets).doubleValue()>0&&row.opt("marketValue") instanceof Number?round(row.getDouble("marketValue")/((Number)assets).doubleValue()*100):JSONObject.NULL).put("totalPnl",add(row.opt("realized"),row.opt("unrealized")));JSONObject q=quotes.optJSONObject(row.optString("instrumentId"));if(q==null)q=new JSONObject();row.put("quoteCached",q.optBoolean("cached")).put("quoteSource",q.optString("source"));positions.put(row);}
  List<JSONObject> events=new ArrayList<>();for(int i=0;i<trades.length();i++)if(id.equals(trades.getJSONObject(i).optString("accountId")))events.add(trades.getJSONObject(i));events.sort(Comparator.comparing(t->t.optString("date")));JSONArray cashPath=new JSONArray();double cumulative=0;boolean complete=true;for(JSONObject t:events){String side=t.optString("side");Object amount=known(t.opt("amount"),true);if(!(amount instanceof Number)){Object q=known(t.opt("quantity"),true),price=known(t.opt("price"),true),fee=known(t.opt("fee"),true),tax=known(t.opt("tax"),true);if(side.equals("buy")&&q instanceof Number&&price instanceof Number&&fee instanceof Number)amount=round(((Number)q).doubleValue()*((Number)price).doubleValue()+((Number)fee).doubleValue());if(side.equals("sell")&&q instanceof Number&&price instanceof Number&&fee instanceof Number&&tax instanceof Number)amount=round(((Number)q).doubleValue()*((Number)price).doubleValue()-((Number)fee).doubleValue()-((Number)tax).doubleValue());if(side.equals("dividend")&&q instanceof Number&&price instanceof Number)amount=round(((Number)q).doubleValue()*((Number)price).doubleValue());if(side.equals("fee")&&fee instanceof Number)amount=fee;}
   Object delta=amount instanceof Number?(side.equals("buy")||side.equals("fee")?-1:1)*((Number)amount).doubleValue():JSONObject.NULL;if(delta instanceof Number)cumulative+=((Number)delta).doubleValue();else complete=false;cashPath.put(new JSONObject().put("tradeId",t.opt("id")).put("date",t.optString("date")).put("instrumentId",t.optString("instrumentId")).put("side",side).put("cashDelta",delta).put("cumulativeRecordedFlow",complete?round(cumulative):JSONObject.NULL));}
  List<JSONObject> history=new ArrayList<>();for(int i=0;i<reports.length();i++){JSONObject report=reports.getJSONObject(i);if(!id.equals(report.optString("accountId"))||!report.optString("legacySource").equals("portfolio_snapshots"))continue;JSONObject raw=report.optJSONObject("legacyOriginal");if(raw==null)raw=new JSONObject();String date=raw.optString("snapshot_date");boolean valid=false;try{valid=date.length()==10&&LocalDate.parse(date).toString().equals(date);}catch(Exception ignored){}Object c=known(raw.opt("cash_balance"),true),m=known(raw.opt("total_market_value"),true),a=known(raw.opt("total_assets"),true);history.add(new JSONObject().put("reportId",report.optString("id")).put("date",date).put("dateValid",valid).put("cashBalance",c).put("marketValue",m).put("totalAssets",a).put("totalPnl",known(raw.opt("total_pnl"),false)).put("arithmeticConsistent",c instanceof Number&&m instanceof Number&&a instanceof Number&&Math.abs(((Number)a).doubleValue()-((Number)c).doubleValue()-((Number)m).doubleValue())<=.05).put("sourceLabel",raw.optString("source_label")).put("original",new JSONObject(raw.toString())));}
  history.sort(Comparator.comparing(r->r.optString("date")));JSONArray snapshots=new JSONArray();Object previous=JSONObject.NULL;for(JSONObject row:history){Object value=row.optBoolean("dateValid")&&row.optBoolean("arithmeticConsistent")?row.opt("totalAssets"):JSONObject.NULL;row.put("assetChange",value instanceof Number&&previous instanceof Number?round(((Number)value).doubleValue()-((Number)previous).doubleValue()):JSONObject.NULL).put("isPerformanceReturn",false);previous=value;snapshots.put(row);}
  return new JSONObject().put("schema","native-account-analysis/v1").put("accountId",id).put("positions",positions).put("cost",p.opt("cost")).put("realized",p.opt("realized")).put("unrealized",p.opt("unrealized")).put("fees",p.opt("fees")).put("marketValue",p.opt("marketValue")).put("cashBalance",cash).put("cashAsOf",account.opt("cashAsOf")).put("totalAssets",assets).put("totalPnl",totalPnl).put("cashPath",cashPath).put("recordedCashFlow",complete?round(cumulative):JSONObject.NULL).put("cashFlowComplete",complete).put("history",snapshots).put("performanceReturn",JSONObject.NULL).put("boundary","移动加权成本与已实现/浮动盈亏沿旧账本。净现金流只反映记录的买卖/分红/费用，不推断期初现金或外部出入金；历史只用原始快照，资产变化不是净收益率。现金与行情时点未统一。");
 }
 static String display(Object v){return v==null||v==JSONObject.NULL?"未知":v.toString();}
}
